def generate_and_upload_headers(manifest):
    html_dir = os.path.join(WORK_ROOT, "headers_html")
    png_dir = os.path.join(WORK_ROOT, "headers_png")
    webp_dir = os.path.join(WORK_ROOT, "headers_webp")
    for path in (html_dir, png_dir, webp_dir):
        os.makedirs(path, exist_ok=True)
    lesson_headers = []
    for sec in manifest["sections"]:
        for lesson in sec["lessons"]:
            lid = lesson["id"]
            path = os.path.join(html_dir, f"header-{lid}.html")
            with open(path, "w", encoding="utf-8") as f:
                f.write(header_html(lesson["label"], lesson["title"]))
            lesson_headers.append(lid)
    subprocess.run(["node", os.path.join(ROOT, "scripts", "render_batch.mjs"), html_dir, png_dir, "1920", "420"], check=True)
    urls = {}
    for lid in lesson_headers:
        png = os.path.join(png_dir, f"header-{lid}.png")
        webp = os.path.join(webp_dir, f"header-{lid}.webp")
        subprocess.run(["cwebp", "-q", "82", png, "-o", webp], check=True, stdout=subprocess.DEVNULL)
        url, _ = upload_attachment(str(COURSE_ID), webp, f"header-{lid}.webp")
        urls[lid] = url
        print(f"header {lid} -> {url}")
    return urls


def links_html(keys):
    return "<h3>Полезные ссылки</h3><ul>" + "".join(
        f'<li><a href="{e(SEO_LINKS[key][1])}">{e(SEO_LINKS[key][0])}</a></li>' for key in keys
    ) + "</ul>"


def lesson_html(header_url, workbook_url, lesson_data):
    title, _, objective, project, deliverable, transition, link_keys = lesson_data
    return f"""<p><img src="{e(header_url)}" alt="{e(title)}"></p>
<h2>Что будет на уроке?</h2>
<p>{e(objective)}</p>
<p>Курс построен вокруг одного сквозного проекта: вы выбираете сайт и ведёте его через аудит, карту запросов, контент-план, ссылочную стратегию и итоговый отчёт. Поэтому каждый урок должен заканчиваться не мыслью «я понял термин», а конкретной строкой в рабочем файле.</p>
<p><strong>Файл-практикум:</strong> <a href="{e(workbook_url)}">SEO-Praktikum-183093.xlsx</a>. Держите его открытым рядом с уроком: в нём уже есть листы для брифа, карты страниц, техаудита, запросов, контент-плана, ТЗ, ссылочного плана и финального отчёта.</p>
<h3>Как применять</h3>
<p>{e(project)}</p>
<p>{e(deliverable)}</p>
<ul>
  <li>Привязывайте каждую находку к конкретному URL, а не пишите общую рекомендацию для всего сайта.</li>
  <li>Отделяйте высокий бизнес-эффект от простой правки, которую приятно быстро закрыть.</li>
  <li>Записывайте доказательство: скриншот, URL, показатель, проблему в выдаче или факт из Вебмастера.</li>
  <li>Формулируйте следующий шаг так, чтобы его мог взять в работу разработчик, редактор или владелец сайта.</li>
</ul>
<p><strong>Частая ошибка:</strong> делать SEO-аудит как демонстрацию эрудиции. Клиенту или руководителю не нужен список всех терминов; ему нужен порядок действий. Если рекомендация не отвечает на вопрос «что сделать, зачем и почему сейчас», её нужно переписать.</p>
<h3>Что дальше?</h3>
<p>{e(transition)}</p>
{links_html(link_keys)}
"""


def create_steps(manifest, header_urls, workbook_url):
    content_dir = os.path.join(WORK_ROOT, "content")
    os.makedirs(content_dir, exist_ok=True)
    for sec in manifest["sections"]:
        for lesson in sec["lessons"]:
            lid = lesson["id"]
            body = lesson_html(header_urls[lid], workbook_url, lesson["lesson_data"])
            path = os.path.join(content_dir, f"{lid}.html")
            with open(path, "w", encoding="utf-8") as f:
                f.write(body)
            subprocess.run(["python3", os.path.join(ROOT, "scripts", "push_text_step.py"), str(lid), path], check=True)
            time.sleep(0.5)


def push_icons(manifest):
    mapping = []
    idx = 0
    for sec in manifest["sections"]:
        for lesson in sec["lessons"]:
            icon = "approval" if "Практика:" in lesson["title"] else ICONS[idx % len(ICONS)]
            mapping.append({"lesson_id": lesson["id"], "icon": icon})
            idx += 1
    path = os.path.join(WORK_ROOT, "icon-mapping.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(mapping, f, ensure_ascii=False, indent=2)
    subprocess.run(["python3", os.path.join(ROOT, "scripts", "push_lesson_icons.py"), path], check=True)


def main():
    load_env()
    token = get_token()
    os.makedirs(WORK_ROOT, exist_ok=True)

    update_course_metadata(token)

    workbook_path = os.path.join(WORK_ROOT, "SEO-Praktikum-183093.xlsx")
    create_workbook(workbook_path)
    workbook_url, _ = upload_attachment(str(COURSE_ID), workbook_path, "SEO-Praktikum-183093.xlsx")
    print("workbook ->", workbook_url)

    manifest = build_skeleton(token)
    header_urls = generate_and_upload_headers(manifest)
    create_steps(manifest, header_urls, workbook_url)
    push_icons(manifest)
    print("done", COURSE_ID)


if __name__ == "__main__":
    main()
